int rand_int(int min, int max) {
    if (min == max)
        return max;

    if (min > max) {
        int t = min;
        min = max;
        max = t;
    }

    long r = (long)rand() % (long)(max - min + 1);
    return (int)r + min;
}

double rand_double(void) {
    return (double)rand() / ((double)RAND_MAX + 1);
}

